import pathlib,json,html,shutil
root=pathlib.Path(r'D:\aispace\phonon'); out=root/'web'/'compare-audio';out.mkdir(exist_ok=True)
rows=json.loads((root/'test-output/compare/results.json').read_text(encoding='utf-8-sig'))
labels={'phonon':'Phonon 31m · default','kokoro':'本地 TTS · Kokoro af_maple'}
sections=[]
for sid in ['q1','q2','q3','q4','q5']:
 pair={r['engine']:r for r in rows if r['id']==sid};first=next(iter(pair.values()));cards=[]
 for engine in ['phonon','kokoro']:
  r=pair.get(engine)
  if not r:cards.append(f'<div class="card {engine}"><h3>{labels[engine]}</h3><p>未生成成功，暂无此引擎音频。</p></div>');continue
  name=f'{sid}-{engine}.wav';shutil.copyfile(r['file'],out/name)
  cards.append(f'''<div class="card {engine}"><h3>{labels[engine]}</h3><audio controls preload="metadata" src="/compare-audio/{name}"></audio><a href="/compare-audio/{name}" download>下载 WAV</a><p class="metrics">{r['sampleRate']:,} Hz · {r['duration']:.3f} 秒<br>Peak {r['peak']:.6f} · RMS {r['rms']:.6f}<br>合成耗时 {r['synthSeconds']:.3f} 秒 · RTF {r['rtf']:.3f}</p><p class="scope">{('含模型加载的 CPU 子进程耗时' if engine=='phonon' else ('页面实测 WebGPU FP32 纯合成；模型加载 ' + format(r.get('pageModelLoadSeconds',0), '.3f') + ' 秒'))}</p></div>''')
 sections.append(f'<section><div class="eyebrow">{sid.upper()} · {html.escape(first["focus"])}</div><h2>{html.escape(first["text"])}</h2><div class="pair">'+''.join(cards)+'</div><button class="sequence" type="button">依次播放：Phonon → Kokoro</button></section>')
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>英语试听对比 · Phonon vs 本地 Kokoro</title><style>
*{box-sizing:border-box}body{margin:0;background:#f1f4f9;color:#17243c;font:16px/1.6 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:32px 20px}h1{font-size:32px;margin:8px 0}header p{max-width:900px;color:#54627b}.legend{display:flex;gap:12px;flex-wrap:wrap}.legend span{padding:8px 16px;background:white;border-radius:10px;font-weight:700}.legend .p{color:#375ac9}.legend .k{color:#087761}section{margin:24px 0;background:white;border-radius:18px;padding:24px;box-shadow:0 6px 28px #15254008}h2{font-size:22px;line-height:1.5;margin:8px 0 20px}.eyebrow{color:#64738b;font-size:14px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{border:2px solid;border-radius:12px;padding:18px}.phonon{border-color:#6f88e7;background:#f6f8ff}.kokoro{border-color:#3aa78c;background:#f2fbf8}h3{font-size:23px;margin:0 0 14px}.phonon h3{color:#284bbc}.kokoro h3{color:#056a53}audio{width:100%}a{color:inherit;font-size:14px}.metrics{font-variant-numeric:tabular-nums;margin:12px 0}.scope{font-size:13px;color:#627087}button{margin-top:18px;border:0;background:#253c60;color:white;border-radius:9px;padding:10px 16px;cursor:pointer}aside{background:#fff6db;border-radius:12px;padding:18px;margin-top:20px;font-size:14px}@media(max-width:720px){.pair{grid-template-columns:1fr}main{padding:20px 12px}section{padding:18px}h1{font-size:26px}}
</style><script src="/compare.js" defer></script></head><body><main><header><div>同文案 · 同标点 · 预生成原始 WAV</div><h1>这次，明确听见哪个模型在说话</h1><p>所有朗读句子都不包含模型或产品名称。每句左侧/上方是 Phonon，右侧/下方是本地 Kokoro；大标题明确标注引擎和音色。直接点击播放器即可，不需要等待模型加载。</p><div class="legend"><span class="p">蓝色：Phonon 31m · default</span><span class="k">绿色：本地 TTS · Kokoro af_maple</span></div><aside>试听比较的是两个具体模型和音色的组合，并非同音色实验。音量未归一化，Peak / RMS 为原始 WAV 实测值；音量较大不等于质量较高。Phonon 的耗时包含每次子进程模型加载；Kokoro 是页面报告的 WebGPU FP32 纯合成耗时，模型初始化单列（首次约 296 秒）；Phonon 是 CPU q8，运行设备和精度不同，因此这些时间不是严格同条件性能基准。未进行人工听音评分。</aside></header>'''+''.join(sections)+'''<footer><a href="/">返回 Phonon 英文合成</a> · <a href="http://127.0.0.1:8787/">原本地 Kokoro 页面</a></footer></main></body></html>'''
(root/'web/compare.html').write_text(page,encoding='utf-8')
(root/'web/compare.js').write_text('''document.querySelectorAll('.sequence').forEach(button=>button.addEventListener('click',async()=>{document.querySelectorAll('audio').forEach(a=>a.pause());const players=[...button.closest('section').querySelectorAll('audio')];for(const audio of players){audio.currentTime=0;try{await audio.play();await new Promise(resolve=>{audio.addEventListener('ended',resolve,{once:true});audio.addEventListener('pause',resolve,{once:true});audio.addEventListener('error',resolve,{once:true});});}catch{break;}}}));''',encoding='utf-8')
print('Comparison built:',len(rows),'WAVs')
